('7c2132ff-036c-4af9-a4b3-0b9e168e5f79','MA','a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Merzouga Tours SARL','Street Food Merzouga Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',0.9,91,308,4.1,'active'),
('a41ac3f4-1442-4e0a-9f1c-af36d403f7e0','MA','a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Merzouga Family Kitchen SARL','Table Merzouga Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',6.9,92.8,227,4.9,'active'),
('d87c4105-7dd5-451b-8a7c-14bf52b21c95','MA','a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Merzouga SARL','Le Salon Merzouga','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',6,91.5,22,3.5,'active'),
('04289a2b-f8cb-4a0d-8c3d-b36ec8377e31','MA','a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Desert Nomad Tours SARL','Desert Nomad Tours','desert_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'A Berber family business running camel treks and overnight camps in the dunes since 2005. Basic but authentic — real nomad-style camps with woven tents and campfire music.',5,97.7,134,4.8,'active'),
('04129b9b-8fba-4786-98eb-a913c81364f8','MA','a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Erg Luxury Expeditions SARL','Erg Luxury Expeditions','desert_experience',4,'verified',ARRAY['en','fr','es','it'],'Premium desert experiences with luxury glamping tents (real beds, en-suite bathrooms), gourmet dinners, and 4x4 Land Cruisers. Stargazing with a telescope included.',2.1,93.4,65,4.9,'active'),
('ee023b9b-bcee-49b3-950e-a16c7ee68466','MA','a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dune Riders Merzouga SARL','Dune Riders Merzouga','desert_experience',2,'verified',ARRAY['en','fr'],'A young team of desert enthusiasts offering sandboarding, quad biking, and buggy tours. Half-day and full-day options. Includes picnic lunch and water.',10.5,92.7,205,3.9,'active'),
('b2da8c51-9701-44d9-a6a2-74afbec2eeac','MA','a4444444-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Merzouga Shuttle Express SARL','Merzouga Shuttle Express','transfer',1,'verified',ARRAY['en','fr'],'Affordable shared shuttle service between the airport, train stations, and city hotels. Fixed schedules, comfortable minibuses, and friendly drivers.',7.8,93.9,92,4.3,'active'),
